package com.mewname.app

import androidx.compose.foundation.layout.*
import androidx.compose.material3.*
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.dp

@Composable
internal fun RecentFeaturesHelp() {
    val language = appLanguage()
    val topics = listOf(
        lt(language, "Avisos de códigos promocionais", "Promo code alerts", "Avisos de códigos promocionales") to
            lt(language,
                "Em Códigos promocionais, ative Avisar sobre novos códigos e permita as notificações. A primeira consulta registra os códigos existentes sem avisar. Depois, o app consulta o Leek Duck uma vez por dia com internet e ao atualizar essa tela, avisando sobre novos códigos disponíveis e não resgatados. Toque no aviso para abrir a lista. O Android pode adiar a verificação para economizar bateria; o aviso não é instantâneo. Desative a opção para interromper os avisos.",
                "In Promo codes, enable Notify about new codes and allow notifications. The first check records existing codes silently. Afterwards, the app checks Leek Duck once a day with internet and when refreshing this screen, notifying about new available codes not marked as redeemed. Tap the alert to open the list. Android may delay checks to save battery; alerts are not instant. Disable the option to stop alerts.",
                "En Códigos promocionales, activa Avisar de nuevos códigos y permite las notificaciones. La primera consulta registra los códigos existentes sin avisar. Después, la app consulta Leek Duck una vez al día con internet y al actualizar esta pantalla, avisando de nuevos códigos disponibles sin canjear. Toca el aviso para abrir la lista. Android puede retrasar las consultas para ahorrar batería; los avisos no son instantáneos. Desactiva la opción para detenerlos."),

        lt(language, "Layout de Sugerir nome", "Suggest name layout", "Diseño de Sugerir nombre") to
            lt(language,
                "Em Treinador > Layout > Sugerir nome, escolha Atual ou Compacto e configure as tags de ações, atributos, gênero, tamanhos, fundos e evoluções como texto, ícone com texto ou apenas ícone. Toque no nome da tag para abrir seu modal. Gênero, tamanho, fundo especial e evoluções compartilham as configurações de exibição dentro de cada grupo, mantendo ícones individuais. Gênero também oferece o modo Segmentado. Escolha Com toggle ou Toque no botão independentemente do texto ou ícone. Círculo colorido permite escolher a cor; ícones com moldura própria mantêm a original. Use Escolher ícone para personalizar cada seletor com os ícones de missões e filtros. Ataque legado usa MT de Elite por padrão; o símbolo do apelido permanece independente. Sem ícone mantém o texto visível. A prévia acompanha as escolhas. Toque no seletor para marcar ou desmarcar; pressione um ícone para ver seu significado. As alterações são salvas automaticamente, incluídas no backup e aplicadas no app e na sobreposição. Restaurar padrão recupera a apresentação original sem alterar os formatos de apelido.",
                "In Trainer > Layout > Suggest name, choose Current or Compact and show action, attribute, gender, size, background and evolution tags as text, icon with text or icon only. Tap a tag name to open its settings dialog. Gender, size, special background and evolution options share display settings within each group while keeping individual icons. Gender also supports Segmented mode. Choose With toggle or Tap button independently from text or icons. Colored circle lets you choose a color; icons with built-in frames keep their original frame. Use Choose icon to customize each selector with mission and filter icons. Legacy move defaults to the Elite TM; the nickname symbol stays independent. No icon keeps the text visible. The preview follows your choices. Tap to toggle; hold an icon to see its meaning. Changes are saved automatically, included in backups and used in the app and overlay. Restore default restores the original presentation without changing nickname formats.",
                "En Entrenador > Layout > Sugerir nombre, elige Actual o Compacto y muestra etiquetas de acciones, atributos, género, tamaños, fondos y evoluciones como texto, icono con texto o solo icono. Toca el nombre de una etiqueta para abrir sus ajustes. Género, tamaño, fondo especial y evoluciones comparten ajustes dentro de cada grupo, conservando iconos individuales. Género también ofrece el modo Segmentado. Elige Con interruptor o Tocar botón independientemente del texto o icono. Círculo de color permite elegir el color; los iconos con marco propio conservan el original. Usa Elegir icono para personalizar cada selector con los iconos de misiones y filtros. Ataque legado usa MT élite por defecto; el símbolo del apodo es independiente. Sin icono mantiene el texto visible. La vista previa refleja tus opciones. Toca para activar o desactivar; mantén pulsado un icono para ver su significado. Los cambios se guardan automáticamente, se incluyen en las copias de seguridad y se aplican en la app y la superposición. Restaurar predeterminado recupera la presentación original sin cambiar los formatos de apodo."),
        lt(language, "Lembretes de eventos", "Event reminders", "Recordatorios de eventos") to
            lt(language,
                "No calendário, abra um evento futuro e toque em Lembrar do evento. Autorize notificações e alarmes quando solicitado. O aviso chega no início, mesmo com o app fechado; toque nele para abrir os detalhes. Para desistir, use Cancelar lembrete. Os lembretes são recuperados após reiniciar o celular. Os lembretes futuros também entram no backup. Ao atualizar o calendário, eventos removidos perdem o lembrete; se o nome ou o início mudar, ative-o novamente na nova ocorrência. Se desativar as permissões, reative-as e volte ao app para recuperar os avisos. Se o aparelho estiver desligado, o aviso pode chegar ao ligá-lo, até uma hora depois do início, enquanto o evento estiver ativo.",
                "Open a future calendar event and tap Remind me. Allow notifications and alarms when asked. A notification appears at the start, even when the app is closed; tap it to open details. Use Cancel reminder to stop it. Reminders are restored after restarting the phone. Future reminders are also backed up. Refreshing the calendar removes reminders for deleted events; if the title or start changes, enable the reminder again for the new occurrence. After restoring permissions, return to the app to rearm reminders. If the phone is off, the notification may arrive on restart, within an hour of the start while the event is still active.",
                "Abre un evento futuro del calendario y toca Recordar evento. Permite notificaciones y alarmas cuando se solicite. Recibirás un aviso al inicio, incluso con la app cerrada; tócalo para ver los detalles. Usa Cancelar recordatorio para desactivarlo. Los recordatorios se recuperan al reiniciar el teléfono. Los recordatorios futuros también se incluyen en la copia de seguridad. Al actualizar el calendario, se eliminan los de eventos retirados; si cambia el nombre o el inicio, actívalo de nuevo en la nueva ocasión. Tras restablecer los permisos, vuelve a la app para recuperar los avisos. Si el teléfono estaba apagado, el aviso puede llegar al encenderlo, hasta una hora después del inicio mientras el evento siga activo."),
        lt(language, "Navegação e perfil", "Navigation and profile", "Navegación y perfil") to
            lt(language,
                "A barra inferior acompanha as telas do app. O botão central inicia ou para o modo sobreposição. Perfil abre um painel acima da barra; arraste o traço superior para baixo, toque fora dele, no ícone de perfil ou use Voltar para fechar. O traço também fecha o painel nos submenus. Toque na foto para alterá-la e no lápis para editar os dados. O QR Code abre sozinho em um modal; toque fora ou use Voltar para fechar. O rodapé mostra local nas compilações locais e o número da versão nas releases do GitHub.",
                "The bottom bar stays available across app screens. The centre button starts or stops overlay mode. Profile opens a panel above the bar; drag the top handle down, tap outside, tap Profile again or use Back to close. The handle also closes the panel from submenus. Tap the photo to change it and the pencil to edit your details. The QR code opens in its own dialog; tap outside or use Back to close. The footer identifies the version and whether the build is local or from a release.",
                "La barra inferior permanece en las pantallas del app. El botón central inicia o detiene la superposición. Perfil abre un panel sobre la barra; arrastra la línea superior hacia abajo, toca fuera, Perfil otra vez o Atrás para cerrar. La línea también cierra el panel desde los submenús. Toca la foto para cambiarla y el lápiz para editar los datos. El QR abre un modal propio; toca fuera o Atrás para cerrar. El pie indica la versión y si es una compilación local o de una release."),
        lt(language, "Atualizar o perfil pelo jogo", "Update your profile from the game", "Actualizar el perfil desde el juego") to
            lt(language,
                "Com o modo sobreposição ativo, abra seu perfil de treinador no jogo e toque na sobreposição para ler nome e nível. Na tela do seu código de treinador, repita a leitura para atualizar o código de amizade e guardar o QR Code quando ele for detectado. Uma mensagem confirma a atualização. Dados não encontrados são preservados; equipe e demais dados podem ser corrigidos pelo lápis. Se o QR Code estiver indisponível, faça a leitura da tela do código no jogo.",
                "With overlay mode active, open your own trainer profile in the game and tap the overlay to read your name and level. Repeat on your trainer-code screen to update the friend code and save the QR code when detected. A message confirms the update. Missing fields keep their previous values; use the pencil to correct your team or other details. If the QR code is unavailable, read the code screen in the game.",
                "Con la superposición activa, abre tu perfil de entrenador en el juego y toca la superposición para leer nombre y nivel. Repite en la pantalla de tu código de entrenador para actualizar el código de amistad y guardar el QR si se detecta. Un mensaje confirma la actualización. Los datos no encontrados se conservan; usa el lápiz para corregir equipo u otros datos. Si falta el QR, lee la pantalla del código en el juego."),
        lt(language, "Atalhos da sobreposição", "Overlay shortcuts", "Accesos de la superposición") to
            lt(language,
                "Pressione e segure a sobreposição para abrir os atalhos. Arraste para mudar a posição. Em Perfil → Atalhos da sobreposição, ative ou desative cada opção tocando na linha ou no interruptor; mantenha pelo menos uma ativa. Tudo é salvo automaticamente; reabra o menu da sobreposição para aplicar. Segure e arraste os blocos nesta lista para reorganizar. Os atalhos selecionados aparecem em arcos seguindo essa ordem. Coleções abre sobre o jogo; volte das formas para a lista ou use X para fechar.",
                "Press and hold the overlay to open shortcuts. Drag to reposition it. In Profile → Overlay shortcuts, tap a row or switch to enable or disable an option; keep at least one active. Choices are saved automatically; reopen the overlay menu to apply. Hold and drag rows in this list to reorder. Selected shortcuts appear in arcs in that order. Collections opens over the game; go back from forms to the list or use X to close.",
                "Mantén pulsada la superposición para abrir los accesos. Arrastra para moverla. En Perfil → Accesos de superposición, toca una fila o interruptor para activar o desactivar cada opción; conserva al menos una activa. Se guarda automáticamente; vuelve a abrir el menú para aplicar. Mantén pulsadas y arrastra las filas de esta lista para ordenarlas. Los accesos seleccionados aparecen en arcos siguiendo ese orden. Colecciones se abre sobre el juego; vuelve de las formas a la lista o usa X para cerrar."),
        lt(language, "Layout, idioma e logs", "Layout, language and logs", "Layout, idioma y registros") to
            lt(language,
                "Em Perfil → Layout, escolha Glass, Claro ou Escuro, grade ou lista compacta e o idioma. As alterações são salvas automaticamente. Mostrar opções de log vem desativado; ative para acessar os diagnósticos do perfil, nomes sugeridos e outras leituras. Em Nomes sugeridos → Exportar log, selecione os campos desejados e compartilhe o resultado. No perfil, exporte o log depois de uma leitura. Desativar a opção esconde os controles e preserva os diagnósticos.",
                "In Profile → Layout, choose Glass, Light or Dark, grid or compact list, and language. Changes are saved automatically. Show log options is off by default; enable it to access diagnostics for the profile, suggested names and other readings. In Suggested names → Export log, select fields and share the result. Export the profile log after a reading. Disabling the option hides controls while preserving diagnostics.",
                "En Perfil → Layout, elige Glass, Claro u Oscuro, cuadrícula o lista compacta e idioma. Los cambios se guardan automáticamente. Mostrar opciones de registro está desactivado por defecto; actívalo para acceder a diagnósticos del perfil, nombres sugeridos y otras lecturas. En Nombres sugeridos → Exportar registro, selecciona campos y comparte. Exporta el registro del perfil después de una lectura. Desactivar oculta controles y conserva diagnósticos."),
        lt(language, "Leitura de Pokémon e filtros", "Pokémon readings and filters", "Lectura de Pokémon y filtros") to
            lt(language,
                "Toque na sobreposição sobre os dados do Pokémon para revisar a leitura nas abas Geral, PVP e Extras e escolher um nome sugerido. Confira os dados antes de copiar; Evoluir e Purificar são interruptores. Nas listas de Pokémon e amigos, a leitura pode abrir os filtros salvos correspondentes. O modo sobreposição precisa das permissões de sobreposição e captura de tela; quando necessário, autorize novamente pelo botão central.",
                "Tap the overlay over a Pokémon's details to review the reading in General, PVP and Extras and choose a suggested name. Check the data before copying; Evolve and Purify are switches. On Pokémon and friend lists, reading can open the corresponding saved filters. Overlay mode requires overlay and screen-capture permission; grant them again using the centre button when needed.",
                "Toca la superposición sobre los datos del Pokémon para revisar la lectura en General, PVP y Extras y elegir un nombre sugerido. Revisa los datos antes de copiar; Evolucionar y Purificar son interruptores. En listas de Pokémon y amigos, la lectura puede abrir los filtros guardados correspondientes. La superposición requiere permisos de superposición y captura; autorízalos otra vez desde el botón central si hace falta.")
    )
    Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
        topics.forEach { (title, body) ->
            AppSectionCard(Modifier.fillMaxWidth()) {
                Column(Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Text(title, style = MaterialTheme.typography.titleSmall, fontWeight = FontWeight.SemiBold)
                    Text(body, style = MaterialTheme.typography.bodyMedium)
                }
            }
        }
    }
}